// ResumeClassic (epic-job-applications, slice 2) — a resume SKELETON: one professional single-column page
// laid out from a `ResumeDoc`. It holds no personal data of its own; given no `doc` it shows the fictional
// DEMO_RESUME, which is what the components graph previews.
//
// Built for the two readers a resume has. A PERSON: restrained type, one accent (`--doc-accent`, navy
// unless a theme sets it), white paper. An APPLICANT-TRACKING SYSTEM: real text in reading order, one
// column, standard section headings, semantic elements (h1/h2/ul/li) — nothing drawn, nothing positioned
// out of flow — so text extracted from the PDF reads top to bottom as the page does.
//
// `page` picks the paper (US Letter or A4). The sheet is that size on screen and prints on that paper with
// the margin on `@page`, so a résumé that runs to two pages keeps its margin on both.
import type { CSSProperties } from "react";
import { DEMO_RESUME, formatPeriod, paperCss, type PaperSize, type ResumeDoc, type ResumeItem, type ResumeSection } from "@/features/jobs/lib/documents";

const SHEET = "bsc-doc-resume-classic";
const ACCENT = "var(--doc-accent, #1f3a5f)";
const MUTED = "#4a4a4a";

const CSS = `
.${SHEET} { font-family: "Inter", "Helvetica Neue", Arial, sans-serif; font-size: 10.5pt; line-height: 1.38; }
.${SHEET} h1, .${SHEET} h2, .${SHEET} h3, .${SHEET} p, .${SHEET} ul { margin: 0; }
.${SHEET} ul { padding-left: 1.1em; }
.${SHEET} li { margin: 0.12em 0; }
.${SHEET} a { color: inherit; text-decoration: none; }
.${SHEET} .item { break-inside: avoid; }
.${SHEET} h2 { break-after: avoid; }
`;

const s = {
  header: { borderBottom: `1.5pt solid ${ACCENT}`, paddingBottom: "8pt", marginBottom: "10pt" },
  name: { fontSize: "22pt", fontWeight: 700, letterSpacing: "0.01em", color: "#111" },
  headline: { fontSize: "11pt", color: MUTED, marginTop: "2pt" },
  contact: { fontSize: "9.5pt", color: MUTED, marginTop: "4pt" },
  summary: { marginBottom: "10pt" },
  section: { marginTop: "10pt" },
  h2: { fontSize: "10.5pt", fontWeight: 700, textTransform: "uppercase", letterSpacing: "0.08em", color: ACCENT, borderBottom: "0.5pt solid #c8c8c8", paddingBottom: "2pt", marginBottom: "5pt" },
  item: { marginBottom: "7pt" },
  itemHead: { display: "flex", justifyContent: "space-between", gap: "12pt", alignItems: "baseline" },
  itemTitle: { fontSize: "10.5pt", fontWeight: 600, color: "#111" },
  period: { fontSize: "9.5pt", color: MUTED, whiteSpace: "nowrap" },
  org: { fontSize: "10pt", color: MUTED },
  skill: { margin: "1.5pt 0" },
} satisfies Record<string, CSSProperties>;

function contactParts(doc: ResumeDoc): string[] {
  const h = doc.header;
  return [h.location, h.email, h.phone, ...(h.links ?? [])].filter((x): x is string => !!x && !!x.trim());
}

function Item({ item }: { item: ResumeItem }) {
  const period = formatPeriod(item.start, item.end);
  const where = [item.org, item.location].filter(Boolean).join(" · ");
  return (
    <article className="item" style={s.item} data-sources={item.sources?.join(" ")}>
      <header style={s.itemHead}>
        <h3 style={s.itemTitle}>{item.title}</h3>
        {period && <p style={s.period}>{period}</p>}
      </header>
      {where && <p style={s.org}>{where}</p>}
      {item.bullets && item.bullets.length > 0 && (
        <ul>
          {item.bullets.map((b, i) => (
            <li key={i} data-sources={b.sources?.join(" ")}>{b.text}</li>
          ))}
        </ul>
      )}
      {item.tags && item.tags.length > 0 && <p style={s.org}>{item.tags.join(", ")}</p>}
    </article>
  );
}

function Section({ section }: { section: ResumeSection }) {
  if (section.items.length === 0) return null;
  return (
    <section style={s.section} aria-label={section.title}>
      <h2 style={s.h2}>{section.title}</h2>
      {section.kind === "skills"
        ? section.items.map((it, i) => (
            <p key={i} style={s.skill} data-sources={it.sources?.join(" ")}>
              <strong>{it.title}:</strong> {(it.tags ?? []).join(", ")}
            </p>
          ))
        : section.items.map((it, i) => <Item key={i} item={it} />)}
    </section>
  );
}

export function ResumeClassic({ doc = DEMO_RESUME, page = "letter" }: { doc?: ResumeDoc; page?: PaperSize }) {
  return (
    <article className={SHEET} data-paper={page} data-document="resume">
      <style>{`${paperCss(page, SHEET)}\n${CSS}`}</style>
      <header style={s.header}>
        <h1 style={s.name}>{doc.header.name}</h1>
        {doc.header.headline && <p style={s.headline}>{doc.header.headline}</p>}
        {contactParts(doc).length > 0 && <p style={s.contact}>{contactParts(doc).join("  ·  ")}</p>}
      </header>
      {doc.summary && (
        <p style={s.summary} data-sources={doc.summary.sources?.join(" ")}>{doc.summary.text}</p>
      )}
      {doc.sections.map((sec, i) => <Section key={i} section={sec} />)}
    </article>
  );
}

export default ResumeClassic;

