// ResumeClassic (epic-job-applications, slice 2) — every fact reaches the page as real text, in reading
// order, and the paper is the one asked for.
import { describe, it, expect } from "vitest";
import { render, screen } from "@testing-library/react";
import { ResumeClassic } from "@/features/jobs/ResumeClassic";
import { DEMO_RESUME, type ResumeDoc } from "@/features/jobs/lib/documents";

describe("ResumeClassic", () => {
  it("renders the demo resume when given no content", () => {
    render(<ResumeClassic />);
    expect(screen.getByRole("heading", { level: 1, name: DEMO_RESUME.header.name })).toBeTruthy();
    for (const sec of DEMO_RESUME.sections) expect(screen.getByRole("heading", { level: 2, name: sec.title })).toBeTruthy();
  });

  it("prints every bullet as text, in the order the content gives it", () => {
    const { container } = render(<ResumeClassic />);
    const text = container.textContent ?? "";
    const bullets = DEMO_RESUME.sections.flatMap((s) => s.items.flatMap((i) => (i.bullets ?? []).map((b) => b.text)));
    let at = -1;
    for (const b of bullets) {
      const next = text.indexOf(b);
      expect(next, `missing or out of order: ${b}`).toBeGreaterThan(at);
      at = next;
    }
  });

  it("renders only the content it is given — no demo data leaks into a real document", () => {
    const doc: ResumeDoc = {
      schema: "resume@1",
      header: { name: "Sam Park" },
      sections: [{ kind: "experience", title: "Experience", items: [{ title: "Engineer", org: "Acme", start: "2020-01", end: "present", bullets: [{ text: "Shipped it.", sources: ["acme-ship"] }] }] }],
    };
    const { container } = render(<ResumeClassic doc={doc} />);
    const text = container.textContent ?? "";
    expect(text).toContain("Jan 2020 – Present");
    expect(text).not.toContain(DEMO_RESUME.header.name);
    expect(container.querySelector("li")?.getAttribute("data-sources")).toBe("acme-ship");
  });

  it("sizes the sheet and the print page for the paper asked", () => {
    const { container, rerender } = render(<ResumeClassic />);
    expect(container.querySelector("[data-paper]")?.getAttribute("data-paper")).toBe("letter");
    expect(container.querySelector("style")?.textContent).toContain("size: letter");
    rerender(<ResumeClassic page="a4" />);
    expect(container.querySelector("style")?.textContent).toContain("size: A4");
  });

  it("drops an empty section rather than printing a bare heading", () => {
    const doc: ResumeDoc = { ...DEMO_RESUME, sections: [{ kind: "projects", title: "Projects", items: [] }] };
    render(<ResumeClassic doc={doc} />);
    expect(screen.queryByRole("heading", { level: 2, name: "Projects" })).toBeNull();
  });
});
